-- FBMN / P0-B. Generated from Owner-provided PRELIMINARY workbook (182 schools).
-- IMPORTANT: this is a staging/seed migration, NOT an exhaustive 13-province registry.
-- 0 verified coordinates. Maps URLs are SEARCH links, not precise route waypoints.
-- Do not run before committing this migration to the original MCP-FBMN main and passing CI.
-- Migration is additive, idempotent for source_ref, and does not change customers.
BEGIN;
CREATE TABLE IF NOT EXISTS public.schools (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_ref text NOT NULL UNIQUE,
  name text NOT NULL,
  education_level text NOT NULL,
  province_old text NOT NULL,
  district_old text NOT NULL,
  ward_old text,
  address_text text NOT NULL,
  maps_search_url text,
  latitude double precision,
  longitude double precision,
  gps_verified boolean NOT NULL DEFAULT false,
  address_detail_level text,
  source_url text,
  verification_note text,
  source_batch text NOT NULL DEFAULT '2026-11-15-preliminary',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT schools_latitude_valid CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90),
  CONSTRAINT schools_longitude_valid CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180),
  CONSTRAINT schools_coordinates_pair CHECK((latitude IS NULL)=(longitude IS NULL)),
  CONSTRAINT schools_verified_coordinates_required CHECK(NOT gps_verified OR latitude IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS schools_old_geography_idx
 ON public.schools(province_old, district_old, name);
CREATE INDEX IF NOT EXISTS schools_search_name_idx ON public.schools(lower(name));
REVOKE ALL ON public.schools FROM PUBLIC;
-- Existing sales_api backend can read shared school directory. HTTP endpoints
-- must still authenticate and check role/scope; never expose public direct access.
GRANT SELECT ON public.schools TO sales_api;
