COMMIT;
-- Must return 182 for first successful import; subsequent imports add no duplicates.
SELECT count(*) AS imported_seed_rows FROM public.schools
 WHERE source_batch = '2026-11-15-preliminary';
SELECT count(*) AS verified_gps_rows FROM public.schools
 WHERE source_batch = '2026-11-15-preliminary' AND gps_verified;
-- Referential/name duplicate review (does not delete or overwrite any school):
SELECT province_old, district_old, lower(btrim(name)) AS normalized_name, count(*)
FROM public.schools GROUP BY province_old, district_old, lower(btrim(name))
HAVING count(*) > 1;